/* V201 real browser screenshot comparison: same state and viewport, V200 vs V201.
 * 13 actual illustrations generated by user request, not fake event photography.
 */
const { chromium } = require("playwright");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const crypto = require("node:crypto");
const out = "screenshots/gs-v201-illustrated-categories";
fs.mkdirSync(out, {recursive:true});
const hash=name=>crypto.createHash("sha256").update(fs.readFileSync(out+"/"+name)).digest("hex");
async function ready(page){
 await page.locator(".gs173-events[data-hydrated=true]").waitFor({timeout:25000});
 await page.evaluate(()=>document.fonts.ready);
}
async function party(page){
 await ready(page);
 const btn=page.locator(".gs173-setlist__select").nth(4);
 await btn.click();
 await page.waitForFunction(()=>document.querySelector(".gs173-cues__eyebrow")?.textContent?.includes("Petreceri private"),null,{timeout:20000});
 await page.waitForFunction(()=>document.querySelector(".gs173-photobox__caption h2")?.textContent?.includes("Petreceri private"),null,{timeout:20000});
 assert.equal(await page.locator(".gs173-setlist__item").nth(4).getAttribute("data-active"),"true");
}
async function overflow(page,where){
 const width=await page.evaluate(()=>[document.documentElement.scrollWidth,document.documentElement.clientWidth]);
 assert(width[0]<=width[1]+2,where+" horizontal overflow "+width);
}
(async()=>{
 const browser=await chromium.launch({headless:true,args:["--no-sandbox","--disable-dev-shm-usage"]});
 try{
  for(const [phase,port,widths] of [["before",4176,[390,1440]],["after",4175,[360,390,430,768,1440,1920]]]){
    for(const width of widths){
      const page=await browser.newPage({viewport:{width,height:900},deviceScaleFactor:1,reducedMotion:"reduce"});
      const errors=[];page.on("pageerror",error=>errors.push(error.message));
      assert.equal((await page.goto("http://127.0.0.1:"+port+"/evenimente",{waitUntil:"domcontentloaded",timeout:60000})).status(),200);
      await party(page);await overflow(page,phase+" events "+width);
      await page.locator("#gs173-setlist-title").evaluate(el=>window.scrollTo({top:Math.max(0,el.getBoundingClientRect().top+scrollY-115),behavior:"instant"}));
      await page.screenshot({path:out+"/"+phase+"-events-viewport-"+width+".png",animations:"disabled"});
      if(width===390||width===1440){
        await page.locator(".gs173-setlist").screenshot({path:out+"/"+phase+"-event-icons-"+width+".png",animations:"disabled"});
      }
      if(phase==="after"){
        assert.equal(await page.locator(".gs201-events .gs201-cue__art").count(),5);
        const selected=page.locator(".gs173-setlist__item").nth(4).locator(".gs201-cue");
        const bgi=await selected.locator(".gs201-cue__art").evaluate(el=>getComputedStyle(el).backgroundImage);
        assert(bgi.includes("gs-category-illustrations-v201.webp"),"the real atlas must be rendered");
        assert.equal(await selected.getAttribute("data-play"),"true");
        const animation=await selected.locator(".gs201-cue__art").evaluate(el=>getComputedStyle(el).animationName);
        assert.equal(animation,"none","reduce motion must not animate illustration");
        await page.locator(".gs173-setlist__select").nth(4).focus();
        await page.keyboard.press("ArrowLeft");
        assert.equal(await page.locator(".gs173-setlist__item").nth(3).getAttribute("data-active"),"true");
        assert.equal(await page.locator(".gs173-setlist__select").nth(3).evaluate(el=>document.activeElement===el),true);
        await page.evaluate(()=>document.documentElement.setAttribute("data-gs-performance","lite"));
        assert((await selected.locator(".gs201-cue__art").evaluate(el=>getComputedStyle(el).backgroundImage)).includes("gs-category-illustrations-v201.webp"),"Lite keeps the generated image");
        assert.equal(await selected.locator(".gs201-cue__art").evaluate(el=>getComputedStyle(el).animationName),"none","Lite artwork remains beautiful but static");
      }
      assert.deepEqual(errors,[],"JS errors "+phase+" "+width);
      console.log("PASS events",phase,width);
      await page.close();
    }
  }
  for(const width of [390,1440]){
    assert.notEqual(hash("before-events-viewport-"+width+".png"),hash("after-events-viewport-"+width+".png"),"real screen difference "+width);
  }
  // All 8 services use the same locally served atlas and native text links.
  for(const width of [390,1440]){
    const page=await browser.newPage({viewport:{width,height:900},deviceScaleFactor:1,reducedMotion:"no-preference"});
    assert.equal((await page.goto("http://127.0.0.1:4175/servicii",{waitUntil:"domcontentloaded"})).status(),200);
    assert.equal(await page.locator(".rs-service-index .gs201-cue__art").count(),8);
    await page.locator(".rs-service-index").scrollIntoViewIfNeeded();
    await overflow(page,"services "+width);
    await page.locator(".rs-service-index").screenshot({path:out+"/after-services-section-"+width+".png",animations:"disabled"});
    const dj=page.locator(".rs-service-index li a").filter({has:page.locator('.gs201-cue[data-kind="dj-mc"]')}).first();
    await page.emulateMedia({reducedMotion:"no-preference"});
    await page.evaluate(()=>document.documentElement.setAttribute("data-gs-performance","full"));
    await dj.hover();
    await page.waitForFunction(() => {
      const item=document.querySelector('.rs-service-index .gs201-cue[data-kind="dj-mc"] .gs201-cue__art');
      if(!item) return false;
      const matrix=getComputedStyle(item).transform;
      return matrix !== "none" && matrix !== "matrix(1, 0, 0, 1, 0, 0)";
    },null,{timeout:3000});
    const hoverTransform=await dj.locator(".gs201-cue__art").evaluate(el=>getComputedStyle(el).transform);
    assert.notEqual(hoverTransform,"none","DJ artwork reacts to hover in full-motion");
    await dj.screenshot({path:out+"/after-dj-hover-"+width+".png",animations:"allow"});
    await page.evaluate(()=>document.documentElement.setAttribute("data-gs-performance","lite"));
    assert((await dj.locator(".gs201-cue__art").evaluate(el=>getComputedStyle(el).backgroundImage)).includes("gs-category-illustrations-v201.webp"),"services Lite keeps the generated image");
    assert.equal(await dj.locator(".gs201-cue__art").evaluate(el=>getComputedStyle(el).animationName),"none");
    await page.close();
  }
  // Validate actual binary is not a CSS substitute/placeholder.
  const verify=await browser.newPage();
  const res=await verify.request.get("http://127.0.0.1:4175/media/gs-category-illustrations-v201.webp");
  assert.equal(res.status(),200,"atlas must be a real HTTP asset");
  assert.match(res.headers()["content-type"]||"",/webp/);
  assert((await res.body()).length>40000,"full optimized artwork bytes");
  const loaded=await verify.evaluate(async()=>{
    const img=new Image();img.src="/media/gs-category-illustrations-v201.webp";
    await img.decode();return {width:img.naturalWidth,height:img.naturalHeight};
  });
  assert.deepEqual(loaded,{width:1120,height:320});
  await verify.close();
  // Explicit click triggers a finite animation, initial state is static; replay works.
  const motion=await browser.newPage({viewport:{width:390,height:900},deviceScaleFactor:1,reducedMotion:"no-preference"});
  await motion.goto("http://127.0.0.1:4175/evenimente",{waitUntil:"domcontentloaded"});
  await ready(motion);
  await motion.evaluate(()=>document.documentElement.setAttribute("data-gs-performance","full"));
  const btn=motion.locator(".gs173-setlist__select").nth(4);
  assert.equal(await btn.locator(".gs201-cue__art").evaluate(e=>getComputedStyle(e).animationName),"none");
  await btn.click();
  assert.match(await btn.locator(".gs201-cue__art").evaluate(e=>getComputedStyle(e).animationName),/gs201-art-tap/);
  await motion.waitForTimeout(170);
  await btn.screenshot({path:out+"/after-party-interaction-full-motion-390.png",animations:"allow"});
  const oldHandle=await btn.locator(".gs201-cue").elementHandle();
  await btn.click();
  assert.equal(await oldHandle.evaluate(e=>e.isConnected),false,"reselection replaces cue and replays");
  await motion.close();
  // Native text and image survives SSR with JavaScript disabled.
  const ctx=await browser.newContext({javaScriptEnabled:false,viewport:{width:390,height:900}});
  for(const [path,expected] of [["/evenimente",5],["/servicii",8]]){
    const page=await ctx.newPage();
    assert.equal((await page.goto("http://127.0.0.1:4175"+path,{waitUntil:"domcontentloaded"})).status(),200);
    assert.equal(await page.locator(".gs201-cue__art").count(),expected);
    assert.equal(await page.locator(path==="/evenimente"?".gs173-setlist__route":".rs-service-index li a").count(),expected);
    await page.close();
  }
  await ctx.close();
  console.log("PASS real 13 illustrations and all responsive, no-JS, image HTTP, keyboard, motion and Lite checks");
 }finally{await browser.close()}
})().catch(e=>{console.error(e);process.exitCode=1});
